      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  };

  onMount(() => {
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce || !("IntersectionObserver" in window)) {
      setValue(props.end);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            start();
            io.disconnect();
          }
        }
      },
      { threshold: 0.5 }
    );
    io.observe(el);
    onCleanup(() => {
      io.disconnect();
      cancelAnimationFrame(raf);
    });
  });

  return (
    <div
      ref={el}
      class="bg-gradient-to-r from-indigo-400 via-fuchsia-400 to-cyan-400 bg-clip-text text-6xl font-extrabold tabular-nums text-transparent sm:text-8xl"
      aria-label={`${format(props.end)}${props.suffix ?? ""}`}
    >
      <span aria-hidden="true">
        {format(value())}
        {props.suffix ?? ""}
      </span>
    </div>
  );
}

