import { createSignal, JSX, onCleanup, onMount } from "solid-js";

type Props = {
  children: JSX.Element;
  delay?: number;
  reduced?: boolean;
};

export default function Reveal(props: Props) {
  const [visible, setVisible] = createSignal(false);
  let el!: HTMLDivElement;

  onMount(() => {
    if (typeof IntersectionObserver === "undefined") {
      setVisible(true);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setVisible(true);
          io.disconnect();
        }
      },
      { threshold: 0.2 }
    );
    io.observe(el);
    onCleanup(() => io.disconnect());
  });

  return (
    <div
      ref={el}
      style={{
        opacity: visible() ? 1 : 0,
        transform: props.reduced || visible() ? "none" : "translateY(32px)",
        transition: props.reduced
          ? "none"
          : `opacity 700ms ease ${props.delay ?? 0}ms, transform 700ms ease ${props.delay ?? 0}ms`,
      }}
      class="h-full"
    >
      {props.children}
    </div>
  );
}

