import { createSignal, onCleanup, onMount } from "solid-js";

type Props = {
  target: number;
  duration?: number;
  reduced?: boolean;
};

export default function Counter(props: Props) {
  const [value, setValue] = createSignal(0);
  let el!: HTMLDivElement;
  let raf = 0;
  let started = false;

  const format = (n: number) =>
    new Intl.NumberFormat("es-AR").format(Math.round(n));

  const start = () => {
    if (started) return;
    started = true;
    if (props.reduced) {
      setValue(props.target);
      return;
    }
    const duration = props.duration ?? 2000;
    const t0 = performance.now();
    const tick = (now: number) => {
      const p = Math.min((now - t0) / duration, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      setValue(props.target * eased);
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  };

  onMount(() => {
    if (typeof IntersectionObserver === "undefined") {
      start();
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          start();
          io.disconnect();
        }
      },
      { threshold: 0.5 }
    );
    io.observe(el);
    onCleanup(() => io.disconnect());
  });

  onCleanup(() => cancelAnimationFrame(raf));

  return (
    <div
      ref={el}
      class="text-6xl font-extrabold tabular-nums sm:text-8xl"
      aria-label={`${format(props.target)} más`}
    >
      <span aria-hidden="true">{format(value())}+</span>
    </div>
  );
}
